def find_path(graph, start, goal):
    # Check if the start and goal are not in the graph, return None
    if start not in graph or goal not in graph:
        return None

    # Set of visited nodes
    visited = set()

    # List for storing the path
    path = []

    # Helper function to perform DFS
    def dfs(node, goal, path):
        if node == goal:
            path.append(goal)
            return True
        visited.add(node)
        for neighbor in graph[node]:
            if neighbor not in visited:
                if dfs(neighbor, goal, path):
                    path.append(node)
                    return True
        return False

    # Start the DFS from the start node
    dfs(start, goal, path)

    # If the goal is in the path, return the path from start to goal
    if goal in path:
        return path
    else:
        return None
