from collections import deque

def find_path(graph, start, goal):
    if start == goal:
        return [start]  # If start and goal are the same, we found a path of length 1.

    visited = set()  # To keep track of visited nodes.
    path_queue = deque()  # For BFS, we use a queue.
    path_queue.append((start, [start]))  # Start with the start node and a path containing just the start node.

    while path_queue:
        (current_node, path) = path_queue.popleft()  # Pop the leftmost node and its path.

        if current_node not in visited:
            visited.add(current_node)  # Mark the node as visited.

            if current_node == goal:
                return path  # If the goal node is reached, return the path.

            # Add all unvisited neighbors to the queue.
            for neighbor in graph.get(current_node, []):
                if neighbor not in visited:
                    path_queue.append((neighbor, path + [neighbor]))  # Add neighbor to the queue with updated path.

    return None  # If no path is found, return None.
