def find_path(graph, start, goal):
    """
    This function finds the path from start to goal in a directed graph represented as a dictionary of lists. 
    The function returns a list of nodes from start to goal (inclusive) or None if the goal is not reachable.
    """
    visited = set()  # Set to keep track of visited nodes
    path = {start: [start]}  # Dictionary to store the path from start to each node

    def search(node):
        if node == goal:
            return True, path[node]

        if node not in visited:
            visited.add(node)
            for neighbor in graph.get(node, []):
                if neighbor not in visited:
                    path[neighbor] = path[node] + [neighbor]
                    is_found, full_path = search(neighbor)
                    if is_found:
                        return True, full_path
            return False, None

    is_found, path = search(start)
    return path if is_found else None
