    def find_path(self, start, goal):
        if start not in self.graph or goal not in self.graph:
            return None

        # Initialize the path list
        path = [start]
        visited = set()
        unvisited = {node: None for node in self.graph}  # using None as +inf
        unvisited[start] = 0

        while unvisited:
            current_node = min(unvisited, key=lambda node: unvisited[node])
            if current_node == goal:
                break

            for neighbor in self.graph[current_node]:
                if neighbor in unvisited:
                    old_cost = unvisited[current_node]
                    new_cost = unvisited[current_node] + 1
                    if unvisited[neighbor] is None or unvisited[neighbor] > new_cost:
                        unvisited[neighbor] = new_cost
            unvisited[current_node] = None

            visited.add(current_node)
            path.append(current_node)

            if current_node == start:
                path.pop()  # Remove start node as it's not part of the path from start to goal

        if unvisited[goal] is None:
            return None
        else:
            return path

