    def add_edge(self, from_node_id, to_node_id):
        if from_node_id not in self.nodes:
            self.add_node(from_node_id)
        if to_node_id not in self.nodes:
            self.add_node(to_node_id)
        self.nodes[from_node_id].neighbors.append(self.nodes[to_node_id])
        self.edge_count += 1

    def __repr__(self):
        return str(self.nodes)

def find_path(graph, start, goal):
    if start not in graph.nodes or goal not in graph.nodes:
        return None

    start_node = graph.nodes[start]
    goal_node = graph.nodes[goal]

    if start_node is goal_node:
        return [start]

    visited = set()
    to_visit = [(start_node, [start])]

    while to_visit:
        current_node, path = to_visit.pop(0)
        visited.add(current_node)

        for neighbor in current_node.neighbors:
            if neighbor not in visited:
                if neighbor is goal_node:
                    return path + [neighbor.id]
                else:
                    to_visit.append((neighbor, path + [neighbor.id]))

    return None

