def find_path(graph, start, goal):
    """
    Finds a path from start to goal in the graph using a path search algorithm.
    """
    if start == goal:
        return [start)

    # Keep track of visited nodes to avoid cycles
    visited = set()
    # Store the path from start to the current node
    path = []

    def search(node):
        if node in visited:
            return False
        visited.add(node)
        if node == goal:
            return True
        path.append(node)
        for neighbor in graph.get(node, []):
            if search(neighbor):
                return True
        path.pop()
        return False

    search(start)
    return path if path else None
